def cyclic_sort(a):
    i, n = 0, len(a)
    while i < n:
        home = a[i] - 1
        if 0 <= home < n and a[home] != a[i]:
            a[i], a[home] = a[home], a[i]    # send home
        else:
            i += 1                            # placed OR out-of-range
